import { test } from 'node:test';
import assert from 'node:assert';
import { createState, frame, collides } from '../game/neon.js';

const ctx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('D1: No deflection - Ball should change velocity upon brick collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + state.ball.r + 1;
  state.ball.vy = -100;
  state.ball.y -= 10; 

  const initialVy = state.ball.vy;
  frame(ctx, state);
  assert.notStrictEqual(state.ball.vy, initialVy, 'Ball vy should change');
});

test('D2: Sticky collision - Ball should be pushed out of brick after collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + state.ball.r + 1;
  state.ball.vy = -100;
  state.ball.y -= 10; 

  frame(ctx, state);
  assert.strictEqual(collides(state.ball, brick), false, 'Ball should not overlap brick after resolution');
});

test('D3: Wrong axis - Ball should flip vx when hitting the side', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball to the left of the brick
  state.ball.x = brick.x - state.ball.r - 1;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100;
  state.ball.x += 10;

  const initialVx = state.ball.vx;
  const initialVy = state.ball.vy;
  frame(ctx, state);

  assert.notStrictEqual(state.ball.vx, initialVx, 'Ball vx should change');
  assert.strictEqual(state.ball.vy, initialVy, 'Ball vy should not change when hitting side');
});

test('D4: Tunneling - Ball should not skip brick at high speed', () => {
  const state = createState(10); // High speed
  const brick = state.bricks[0];
  // Place ball just above the brick, but with a velocity that would put it below in one frame
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = 1000; // Way too fast

  // Simulate one step of movement before frame()
  // Step doesn't handle bricks, so it just moves the ball
  // Since we are testing frame(), let's just set the position to 'inside' or 'past'
  // Actually, the tunneling test usually requires checking the path between frames.
  // In the current implementation, if the ball was at y=40 and now is at y=80, and brick is at 50-70, 
  // collides() will return false both times.

  // For now, let's just verify that a ball that 'jumped' the brick still triggers collision
  // (This is impossible with current collides(), which is the point).
  state.ball.y = brick.y + brick.h + state.ball.r + 1; // Ball is now below the brick
  // The ball was above the brick in the previous "virtual" frame.

  // Since frame() only checks current position, it can't detect tunneling.
  // To prove this, we'd need a test that sets the ball at a position where it 
  // would have crossed the brick in the last dt.

  // For the purpose of this TDD cycle, I'll just document it as a defect 
  // and write a test that fails if a 'jump' occurs.
  // But wait, current frame() logic ONLY calls collides().
  // If the ball is not currently overlapping, no collision is detected.
});

