// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Now also handles bricks to avoid tunneling.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Store previous position for tunneling detection if needed, 
  // but for now we use sub-stepping for simplicity.
  const subSteps = 4;
  const sdt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * sdt;
    ball.y += ball.vy * sdt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM): brick collision logic STILL mixed in here ------------

// Main render loop. For each live brick we test collision AND draw in the same
// pass: this is where logic and rendering are entangled.
export function frame(ctx, state) {
  let flippedX = false;
  let flippedY = false;

  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // Collision resolution: determine which face was hit by finding the smallest penetration
      const overlapLeft = (state.ball.x + state.ball.r) - brick.x;
      const overlapRight = (brick.x + brick.w) - (state.ball.x - state.ball.r);
      const overlapTop = (state.ball.y + state.ball.r) - brick.y;
      const overlapBottom = (brick.y + brick.h) - (state.ball.y - state.ball.r);

      const minOverlap = Math.min(overlapLeft, overlapRight, overlapTop, overlapBottom);

      if (minOverlap === overlapLeft && !flippedX) {
        state.ball.x = brick.x - state.ball.r;
        state.ball.vx = -Math.abs(state.ball.vx);
        flippedX = true;
      } else if (minOverlap === overlapRight && !flippedX) {
        state.ball.x = brick.x + brick.w + state.ball.r;
        state.ball.vx = Math.abs(state.ball.vx);
        flippedX = true;
      } else if (minOverlap === overlapTop && !flippedY) {
        state.ball.y = brick.y - state.ball.r;
        state.ball.vy = -Math.abs(state.ball.vy);
        flippedY = true;
      } else if (minOverlap === overlapBottom && !flippedY) {
        state.ball.y = brick.y + brick.h + state.ball.r;
        state.ball.vy = Math.abs(state.ball.vy);
        flippedY = true;
      }
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

