test('frame: D1 No deflection - Ball should change velocity upon brick collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + state.ball.r + 1;
  state.ball.vy = -100;
  state.ball.y -= 10; 
  step(state, 0.01);
  assert.notStrictEqual(state.ball.vy, -100, 'Ball vy should change');
});

test('frame: D2 Sticky collision - Ball should be pushed out of brick after collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + state.ball.r + 1;
  state.ball.vy = -100;
  state.ball.y -= 10; 
  step(state, 0.01);
  assert.equal(collides(state.ball, brick), false, 'Ball should not overlap brick after resolution');
});

test('frame: D3 Wrong axis - Ball should flip vx when hitting the side', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - state.ball.r - 1;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100;
  state.ball.x += 10;
  step(state, 0.01);
  assert.notStrictEqual(state.ball.vx, 100, 'Ball vx should change');
  assert.equal(state.ball.vy, state.ball.vy, 'Ball vy should not change');
});

test('frame: D4 Tunneling - Ball should not skip brick at high speed', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = 2000; 
  step(state, 0.05);
